                var root = notes[0] || {};
                var body = (root.body || '').trim();
                var pos = root.position || {};
                var resolved = thread.resolved === true || root.resolved === true;
                var path = pos.new_path || pos.old_path || null;
                var line = pos.new_line || pos.old_line || null;

