        assert.notContains(out.markdown, '### Thread 1');
        assert.contains(out.markdown, '### Thread 2\n\n**unknown** ():\nr2\n---\n\n');
        assert.contains(out.markdown, '### Thread 3\n\n**unknown** ():\nr3\n---\n\n');
