function _gitlabRenderThreadSection(mapped, notes) {
    var section = '### Thread ' + mapped.index;
    if (mapped.path) {
        section += ' — `' + mapped.path + '`';
        if (mapped.line) section += ' line ' + mapped.line;
    }
    section += '\n\n';
    var root = notes[0] || {};
    section += mapped.body
        ? ('**' + _gitlabThreadAuthor(root.author) + '** (' + _gitlabThreadDate(root) + '):\n' + mapped.body + '\n')
