        markdown: sections.length > 0
            ? '# PR Discussion History\n\n_Previous review discussions for MR #' + prId + '._\n\n' + sections.join('\n')
            : null,
        rawThreads: rawThreads.length > 0 ? { threads: rawThreads } : null
    };
