/**
 * SCRATCH harness (not committed): byte-equality proof that the refactored
 * GitLab fetchDiscussions output is identical to origin/main's renderer.
 * Loads BOTH scm.js versions with identical mocks and compares byte-for-byte.
 */
/* global loadModule, assert, test, suite, makeRequire */

var REPO = '/home/runner/work/dmtools-agents/dmtools-agents/';
var OLD_PATH = '/tmp/pre-refactor/js/common/scm.js';
var NEW_PATH = REPO + 'js/common/scm.js';

function loadWith(discussionsResult, path) {
    return loadModule(path,
        makeRequire({ './machineNotice.js': loadModule('js/common/machineNotice.js') }),
        { gitlab_get_mr_discussions: function () { return discussionsResult; } });
}

var CASES = [
    {
        name: 'mixed: replies, no-notes placeholder, whitespace body, resolved mix, {value} envelope',
        d: { value: [
            { id: 'd1', resolved: true, notes: [{ body: 'resolved body', author: { username: 'r' }, created_at: '2026-01-01T00:00:00Z' }] },
            { id: 'd2', notes: [
                { body: '  please fix  ', position: { new_path: '/src/a.js', new_line: 12 },
                  author: { username: 'dev1' }, created_at: '2026-02-03T11:00:00Z', resolved: false },
                { body: ' on it ', author: { name: 'Second Dev' }, created_at: '2026-02-04T09:30:00Z' },
                { body: '', author: undefined, created_at: undefined }
            ] },
            { id: 'd3' },
            { id: 'd4', notes: [{ body: '   ' }] },
            { id: 'd5', notes: [{ body: 'old-side', position: { old_path: '/o.js', old_line: 3 } }] },
            { id: 'd6', notes: [{ body: 'empty author obj', author: {} }] }
        ]}
    },
    { name: 'empty list', d: [] },
    { name: 'all resolved → null markdown', d: [{ id: 'd1', resolved: true, notes: [{ body: 'x' }] }] }
];

suite('gitlab fetchDiscussions old-vs-new byte equality', function () {
    CASES.forEach(function (c) {
        test(c.name, function () {
            var oldMod = loadWith(c.d, OLD_PATH);
            var newMod = loadWith(c.d, NEW_PATH);
            var oldOut = oldMod.createScm({ scm: { provider: 'gitlab' }, repository: { owner: 'g', repo: 'r' } }).fetchDiscussions(9);
            var newOut = newMod._gitlabFetchDiscussions('g', 'r', 9);
            // guard against vacuous equality: at least the mixed case must render
            if (c.name.indexOf('mixed') === 0) {
                assert.contains(oldOut.markdown, '### Thread');
                assert.contains(newOut.markdown, '### Thread');
            }
            assert.equal(newOut.markdown, oldOut.markdown);
            assert.equal(JSON.stringify(newOut.rawThreads), JSON.stringify(oldOut.rawThreads));
        });
    });
});

