    if str(match['rootCommentId']) != str(r['inReplyToId']):
        print("MISMATCH inReplyToId:", tid, r['inReplyToId'], "vs", match['rootCommentId']); ok = False
    if 'reply' not in r or not r['reply'].startswith('outputs/review_replies/'):
        print("BAD reply field:", r); ok = False
    import os
    if not os.path.isfile(r['reply']):
        print("MISSING file:", r['reply']); ok = False
# field-name check: must NOT use raw input field names
for r in out['replies']:
    if 'rootCommentId' in r or 'body' in r:
        print("RAW FIELD NAMES LEAKED:", r); ok = False
print("ALL REPLIES VALID" if ok else "FAILURES FOUND")
